import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
ADMIN_TOKEN = os.environ.get('ADMIN_TOKEN', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        key_hash TEXT NOT NULL,
        permissions TEXT DEFAULT 'read',
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role) VALUES ('admin', 'admin@internal.corp', ?, 'superadmin')",
               (hashlib.sha256(b'admin_default_pw').hexdigest(),))
    db.commit()
    db.close()

@app.before_first_request
def setup():
    init_db()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    query_field = request.args.get('field', 'username')
    query_value = request.args.get('q', '')
    limit = request.args.get('limit', '50')

    # Basic field validation
    allowed_fields = ['username', 'email', 'role', 'created_at']
    if query_field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    sql = f"SELECT id, username, email, role, created_at FROM users WHERE {query_field} LIKE ? LIMIT {limit}"

    try:
        db = get_db()
        results = db.execute(sql, (f'%{query_value}%',)).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role, created_at FROM users WHERE id = ?', (user_id,)).fetchone()
    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    try:
        db = get_db()
        db.execute('INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)',
                   (data['username'], data['email'], password_hash))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def admin_export():
    token = request.headers.get('X-Admin-Token', '')
    if not token or token != ADMIN_TOKEN:
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute('SELECT id, username, email, role, password_hash, created_at FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
